-- month-wisdom-03
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Предлагаю вам пройти третий урок месяца мудрости. Он посвящён расктытию мудрости на уровне этики, моральных принципов и общего блага. Вас ожидает интересная практика с этим намерением. Длительность урока - 2 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Предлагаю вам пройти третий урок месяца мудрости. Он посвящён расктытию мудрости на уровне этики, моральных принципов и общего блага. Вас ожидает интересная практика с этим намерением. Длительность урока - 2 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Предлагаю вам пройти третий урок месяца мудрости. Он посвящён расктытию мудрости на уровне этики, моральных принципов и общего блага. Вас ожидает интересная практика с этим намерением. Длительность урока - 2 часа.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly\">Урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='7867efa7-d83e-51a7-8df9-4c386f5cf012';

-- month-wisdom-04
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свобоы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свобоы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свобоы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly\">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='fc123961-3e3c-5e55-b685-4440c662d41f';

-- month-wisdom-05
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца мудрости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца мудрости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца мудрости. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly\">Урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='9c3ad33f-efbc-5246-b6dc-4692cabf96b7';

-- month-wisdom-06
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию пятой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию пятой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё одну внеплановую практику, направленную на гармонизацию пятой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly\">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='cc44270b-8345-5fa0-9caa-d90086841085';

-- month-wisdom-07
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию аджны. Этот урок посвящён способности принимать решения. Вас ожидает специальная практика с этим намерением. Длительность урока - 2 час 22 минуты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Урок 5</a></p><p></p><p>И, так как месяц мудрости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию седьмой чакры - она отвечает за соединённость с тем, что (кто) выше нас. Если первая чакра соединяет нас с Землёй, и даёт физическое здоровье, то седьмая чакра соединяет нас с Небом, и даёт здоровье духовное. Проблема в том, что социум погряз в материализме, в бытовой суете, а религия существенно загрязнена и воспринимается как &quot;опиум для народа&quot;. Поэтому есть над чем поработать. Чтобы ознакомиться с описанием этого месячного практикума и записаться на него, перейдите на страницу - <a href="https://zamkovoi.yoga/m7/">https://zamkovoi.yoga/m7/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif" alt="Месяц мудрости" width="504" height="155" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию аджны. Этот урок посвящён способности принимать решения. Вас ожидает специальная практика с этим намерением. Длительность урока - 2 час 22 минуты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly">Урок 5</a></p><p></p><p>И, так как месяц мудрости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию седьмой чакры - она отвечает за соединённость с тем, что (кто) выше нас. Если первая чакра соединяет нас с Землёй, и даёт физическое здоровье, то седьмая чакра соединяет нас с Небом, и даёт здоровье духовное. Проблема в том, что социум погряз в материализме, в бытовой суете, а религия существенно загрязнена и воспринимается как &quot;опиум для народа&quot;. Поэтому есть над чем поработать. Чтобы ознакомиться с описанием этого месячного практикума и записаться на него, перейдите на страницу - <a href="https://zamkovoi.yoga/m7/">https://zamkovoi.yoga/m7/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-wisdom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-wisdom/m6_email-f78b85e22f8b.gif","alt":"Месяц мудрости","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":163},{"id":"month-wisdom-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию аджны. Этот урок посвящён способности принимать решения. Вас ожидает специальная практика с этим намерением. Длительность урока - 2 час 22 минуты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#156abf;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#156abf;mso-line-height-rule:exactly\">Урок 5</a></p><p></p><p>И, так как месяц мудрости подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию седьмой чакры - она отвечает за соединённость с тем, что (кто) выше нас. Если первая чакра соединяет нас с Землёй, и даёт физическое здоровье, то седьмая чакра соединяет нас с Небом, и даёт здоровье духовное. Проблема в том, что социум погряз в материализме, в бытовой суете, а религия существенно загрязнена и воспринимается как &quot;опиум для народа&quot;. Поэтому есть над чем поработать. Чтобы ознакомиться с описанием этого месячного практикума и записаться на него, перейдите на страницу - <a href=\"https://zamkovoi.yoga/m7/\">https://zamkovoi.yoga/m7/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
